// MineBench: Choo-Choo Train v2
// Steam locomotive + coal tender + passenger car on track with station
// All parts built bottom-up, dependent on parts below

// === TERRAIN BASE - limited area for perf ===
for(var x=64;x<192;x++)for(var z=40;z<220;z++){
  block(x,0,z,'grass_block');
  block(x,1,z,'dirt');
}
for(var x=64;x<192;x++)for(var z=112;z<=143;z++)block(x,2,z,'sand');

// === TRACK ===
for(var z=40;z<200;z++){
  block(121,3,z,'iron_block');
  block(131,3,z,'iron_block');
  if(z%4===0){block(122,3,z,'oak_planks');block(130,3,z,'oak_planks');}
}

// === LOCOMOTIVE BOILER - solid box for guaranteed connectivity ===
box(123,0,80,133,18,110,'stone');
// Gold trim bands at front and back
box(126,1,80,128,18,80,'gold_block');
box(126,1,110,128,18,110,'gold_block');
// Firebox plate
block(128,0,80,'iron_block');

// Boiler dome - connector at y=18 overlaps solid boiler
box(127,18,89,129,18,91,'gold_block');
box(127,19,89,129,21,91,'gold_block');

// === LOCOMOTIVE CAB - oak_planks to distinguish from boiler ===
box(123,0,111,133,17,115,'oak_planks');
box(123,0,115,133,0,115,'cobblestone');
box(123,18,111,133,18,115,'oak_planks');
box(123,10,111,133,15,111,'glass');
box(123,10,113,133,15,113,'glass');
box(128,5,115,130,14,115,'oak_planks');

// === SMOKESTACK ===
var sx=128,sz=78,ssr=2,ssl=7;
for(var dx=-ssr;dx<=ssr;dx++)for(var dz=-ssl/2;dz<=ssl/2;dz++){
  if(dx*dx+dz*dz<=ssr*ssr){
    box(sx+dx,0,sz+dz-ssl/2,sx+dx,24,sz+dz-ssl/2,'iron_block');
  }
}
for(var dx=-3;dx<=3;dx++)for(var dz=-3;dz<=3;dz++){
  if(dx*dx+dz*dz<=9)box(sx+dx,24,sz+dz,sx+dx,24,sz+dz,'iron_block');
}

// === LOCOMOTIVE WHEELS ===
var wy=8,wr=5;
var wz=[85,95,105,110];
for(var wi=0;wi<wz.length;wi++){
  for(var dx=-wr;dx<=wr;dx++)for(var dz=-wr;dz<=wr;dz++){
    if(dx*dx+dz*dz<=wr*wr)box(121+dx,wy-wr,wz[wi]+dz,131+dx,wy-wr,wz[wi]+dz,'iron_block');
  }
}
// Connecting rod
box(121,wy-wr+1,wz[0],131,wy-wr+1,wz[wz.length-1],'iron_block');

// === PILOT / COWCATCHER ===
for(var dz=0;dz<15;dz++){
  var w=15-Math.floor(dz*0.3);
  box(128-Math.floor(w/2),0,80-dz,128+Math.floor(w/2),5,80-dz,'iron_block');
}

// === TENDER - iron_block to distinguish from locomotive ===
var tx=128,tz=128,tr=5;
for(var dx=-tr;dx<=tr;dx++)for(var dz=-12;dz<=12;dz++){
  if(dx*dx+dz*dz<=tr*tr){
    box(tx+dx,0,tz+dz-12,tx+dx,14,tz+dz-12,'iron_block');
  }
}
box(tx-tr,15,tz-12,tx+tr,15,tz+12,'oak_planks');

// Coal pile on tender - prominent black mound
cbox(tx,tr,tz-10,14,8,'black_wool');
function cbox(cx,cy,cz,r,h,t){
  for(var dy=0;dy<h;dy++){
    var rr=r-Math.floor(dy*0.35);
    if(rr<1)rr=1;
    for(var dx=-rr;dx<=rr;dx++)for(var dz=-rr;dz<=rr;dz++){
      if(dx*dx+dz*dz<=rr*rr)box(cx+dx,cy+dy,cz+dz,cx+dx,cy+dy,cz+dz,t);
    }
  }
}

// === PASSENGER CAR - brown_wool to distinguish from everything else ===
box(123,0,140,133,17,172,'brown_wool');
box(123,18,140,133,18,172,'brown_wool');

// Windows carved into solid walls
for(var dz=-14;dz<=14;dz+=3){
  box(123,8,156+dz,123,14,156+dz,'glass');
  box(133,8,156+dz,133,14,156+dz,'glass');
}

// Door in solid wall
box(127,5,156,129,14,156,'oak_planks');

// Platform strips along bottom edge
box(123,1,140,123,3,172,'oak_planks');
box(133,1,140,133,3,172,'oak_planks');

// === STATION PLATFORM ===
box(138,3,80,153,5,140,'stone_bricks');
box(138,3,80,153,3,140,'cobblestone');

// === STATION BUILDING ===
box(138,4,80,153,17,92,'stone');
box(138,4,80,153,4,92,'oak_planks');
box(138,18,80,153,18,92,'oak_planks');
box(140,8,80,143,14,80,'glass');
box(147,8,80,150,14,80,'glass');
box(145,5,92,148,14,92,'oak_planks');

// === BENCH ===
box(140,4,105,146,5,106,'oak_planks');
box(140,6,105,146,6,105,'oak_planks');

// === SIGN ===
box(145,4,108,145,8,108,'oak_log');
box(143,9,107,147,9,109,'oak_planks');

// === TREES ===
function tree(tx,ty,tz){
  box(tx-1,ty,tz-1,tx+1,ty+3,tz+1,'oak_log');
  for(var dx=-4;dx<=4;dx++)for(var dz=-4;dz<=4;dz++)for(var dy=4;dy<=7;dy++){
    if(dx*dx+dz*dz+Math.pow(dy-5.5,2)<=16)box(tx+dx,ty+dy,tz+dz,tx+dx,ty+dy,tz+dz,'oak_leaves');
  }
}
tree(100,0,170);
tree(155,0,165);
